using Dapper; using InovaGed.Application.Common.Database; using InovaGed.Application.Continuity;
namespace InovaGed.Infrastructure.Continuity;
public sealed class RecoveryPlanRepository(IDbConnectionFactory db) : IRecoveryPlanService { public async Task<IReadOnlyList<RecoveryPlanDto>> ListAsync(Guid? tenantId,CancellationToken ct){await using var c=await db.OpenAsync(ct);var rows=await c.QueryAsync<RecoveryPlanDto>(new CommandDefinition("select id, tenant_id TenantId, name, current_version CurrentVersion, status, rpo_minutes RpoMinutes, rto_minutes RtoMinutes, last_test_at_utc LastTestAtUtc, last_test_result LastTestResult, next_review_at_utc NextReviewAtUtc from ged.recovery_plan where (@tenantId is null or tenant_id=@tenantId or tenant_id is null)",new{tenantId},cancellationToken:ct));return rows.AsList();} }
